import 'dart:async';import 'dart:convert';import 'dart:io';import 'package:flutter/material.dart';import 'package:flutter_test/flutter_test.dart';import 'package:flutter_core/component_catalogue.dart' show CatalogueLabels;import 'package:flutter_core/preference_sync/preference_protocol.dart' show PreferenceScope;import 'package:flutter_core/dashboard_widgets.dart';
void main(){final labels=CatalogueLabels.fromMetadata(jsonDecode(File('../primecare_ui/catalogs/dashboard-widgets.registration.json').readAsStringSync()),'en'),fixture=jsonDecode(File('test/dashboard_widgets/model-fixtures.json').readAsStringSync()) as Map<String,Object?>,views=(fixture['views'] as List).map(ViewportSpec.fromJson).toList(),widgets=(fixture['widgets'] as List).map(WidgetSpec.fromJson).toList(),defaults=DashboardLayout.fromJson(fixture['defaults'],widgets,views),colours=[Colors.blue,Colors.green,Colors.red];Widget app(Widget child)=>MaterialApp(home:Scaffold(body:SingleChildScrollView(child:child)));DashboardSession session()=>DashboardSession(scope:PreferenceScope('fixture','fixture','fixture','demo'),resource:'fixture',widgets:widgets,views:views,defaults:defaults);Widget grid(DashboardSession s,{WidgetDataSource? source})=>PrimeDashboardGrid(labels:labels,session:s,scope:'fixture',rowHeight:180,gap:16,chartHeight:180,stroke:2,colours:colours,source:source);
 testWidgets('all chart families expose original values and missing alternatives',(t)async{for(final row in (fixture['charts'] as List).cast<Map<String,Object?>>().take(4)){final data=ChartData.fromJson(row['data']);await t.pumpWidget(app(PrimeChart(labels:labels,data:data,scope:'chart',height:180,stroke:2,colours:colours)));expect(find.byType(DataTable),findsOneWidget);expect(find.byType(CustomPaint),findsWidgets);if(data.kind=='line'){expect(find.text(labels.text('missing')),findsOneWidget);await t.tap(find.text(labels.text('toggle')));await t.pumpAndSettle();expect(find.text(labels.text('empty')),findsOneWidget);}}});
 testWidgets('widget remove and resize remain view-specific and adapters are disabled',(t)async{final s=session();await t.pumpWidget(app(grid(s)));expect(find.text(labels.text('unavailable')),findsWidgets);await t.ensureVisible(find.text(labels.text('wider')).first);await t.tap(find.text(labels.text('wider')).first);await t.pumpAndSettle();expect(s.document.views['wide']!.first.span,3);await t.ensureVisible(find.text(labels.text('remove')).first);await t.tap(find.text(labels.text('remove')).first);await t.pumpAndSettle();expect(s.document.views['wide']!.length,1);expect(s.document.views['small']!.length,1);final save=t.widget<TextButton>(find.ancestor(of:find.text(labels.text('save')),matching:find.byType(TextButton)));expect(save.onPressed,isNull);await t.pumpWidget(const SizedBox());s.dispose();});
 testWidgets('late removed widget results cannot repaint current grid',(t)async{final s=session(),pending=Completer<DashboardWidgetData>();await t.pumpWidget(app(grid(s,source:(id,source,workflow)async=>id=='trend'?pending.future:const MetricWidgetData(1234,'units'))));await t.pumpAndSettle();expect(find.text(labels.text('loading')),findsWidgets);await t.ensureVisible(find.text(labels.text('remove')).first);await t.tap(find.text(labels.text('remove')).first);await t.pumpAndSettle();pending.complete(ChartWidgetData(ChartData.fromJson({'kind':'line','title':'STALE','categories':['A'],'series':[{'id':'one','label':'One','values':[1]}]})));await t.pumpAndSettle();expect(find.text('STALE'),findsNothing);await t.pumpWidget(const SizedBox());s.dispose();});
 testWidgets('source errors and retry are truthful; literal chart title stays text',(t)async{final s=session();var fail=true;await t.pumpWidget(app(grid(s,source:(id,source,workflow)async{if(fail)throw StateError('denied');return id=='metric'?const MetricWidgetData(42,'units'):ChartWidgetData(ChartData.fromJson({'kind':'line','title':'<script>literal</script>','categories':['A'],'series':[{'id':'one','label':'One','values':[1]}]}));})));await t.pumpAndSettle();expect(find.text(labels.text('error')),findsWidgets);fail=false;await t.ensureVisible(find.text(labels.text('retry')).first);await t.tap(find.text(labels.text('retry')).first);await t.pumpAndSettle();expect(find.text('<script>literal</script>'),findsWidgets);await t.pumpWidget(const SizedBox());s.dispose();});
}
